import{_ as o,a0 as p,w as s,s as u,ao as a,I as e,a1 as n,A as l,x as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"监控微服务的五原则 | LCTT x X-CMD","titleTemplate":false,"description":"监控微服务的五原则 | LCTT (201612) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"监控微服务的五原则 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"监控微服务的五原则 | LCTT (201612) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201612/20160913 The Five Principles of Monitoring Microservices","title":"监控微服务的五原则","tag":"201612","desc":""},"relativePath":"201612/20160913 The Five Principles of Monitoring Microservices.md","filePath":"[post].md"}'),d={name:"201612/20160913 The Five Principles of Monitoring Microservices.md"};function m(f,t,b,T,g,v){const r=p("Link");return s(),u("div",null,[t[24]||(t[24]=a('<h1 id="监控微服务的五原则" tabindex="-1">监控微服务的五原则 <a class="header-anchor" href="#监控微服务的五原则" aria-label="Permalink to “监控微服务的五原则”">​</a></h1><p><img src="http://thenewstack.io/wp-content/uploads/2016/09/toppicsysdig.jpg" alt=""></p><p>我们对微服务的需求可以归纳为一个词：速度。这种更快提供功能完善且可靠的软件的需求，彻底改变了软件开发模式。毫无疑问，这个改变对软件管理，包括系统监控的方式，都产生了影响。在这篇文章里，我们将重点关注放在有效地监控产品环境中的微服务所需做出的主要改变。我们将为这一新的软件架构拟定 5 条指导性原则来调整你的监控方法。</p><p>监控是微服务控制系统的关键部分，你的软件越复杂，那么你就越难了解其性能及问题排障。鉴于软件交付发生的巨大改变，监控系统同样需要进行彻底的改造，以便在微服务环境下表现更好。下面我们将介绍监控微服务的 5 条原则，如下：</p><ol><li>监控容器及其里面的东西。</li><li>在服务性能上做监控，而不是容器性能。</li><li>监控弹性和多地部署的服务。</li><li>监控 API。</li><li>将您的监控映射到您的组织结构。</li></ol><p>利用这 5 条原则，你可以在向微服务前进的道路上，建立更有效的对微服务的监控。这些原则，可以让你应对随着微服务而来的技术变化和组织变化。</p><h3 id="微服务监控的原则" tabindex="-1">微服务监控的原则 <a class="header-anchor" href="#微服务监控的原则" aria-label="Permalink to “微服务监控的原则”">​</a></h3><h4 id="_1、监控容器及其里面的东西" tabindex="-1">1、监控容器及其里面的东西 <a class="header-anchor" href="#_1、监控容器及其里面的东西" aria-label="Permalink to “1、监控容器及其里面的东西”">​</a></h4><p>容器因构建微服务而凸显其重要性，容器的速度、可移植性和隔离特性让开发者很容易就爱上了微服务模型。容器的好处已经写的够多了，毋庸赘述。</p><p>容器对于其外围的系统来说就像是黑盒子。这对于开发来说大有裨益，从开发环境到生产环境，甚至从开发者的笔记本到云端，为它们带来高度的可移植性。但是当运行起来后，监控和解决服务问题时，这个黑盒子让常规的方法难以奏效了，我们会想：容器里到底在运行着什么？程序和代码运行性能如何？它有什么重要的输出指标吗？从 DevOps 的视角，你需要对容器有更深的了解而不是仅仅知道有一些容器的存在。</p><p><img src="http://thenewstack.io/wp-content/uploads/2016/09/greatfordev.jpg" alt=""></p><p>非容器环境下衡量的典型做法，是让一个代理程序运行在主机或者虚机上的用户空间里，但这并不适用于容器。因为容器的优点是小，将各种进程分离开来，并尽可能的减少依赖关系。</p><p>而且，从规模上看，成千上万的监测代理，对即使是一个中等大小的部署都是一个昂贵的资源浪费和管理的噩梦。对于容器有两个潜在的解决方案：1）要求你的开发人员直接监控他们的代码，或者2）利用一个通用的内核级的检测方法来查看主机上的所有应用程序和容器活动。这里我们不会深入说明，但每一种方法都有其优点和缺点。</p><h4 id="_2、-利用业务流程系统提醒服务性能" tabindex="-1">2、 利用业务流程系统提醒服务性能 <a class="header-anchor" href="#_2、-利用业务流程系统提醒服务性能" aria-label="Permalink to “2、 利用业务流程系统提醒服务性能”">​</a></h4><p>理解容器容器中的运行数据并不容易，一个单一容器相比组成一个功能或服务的容器聚合，测量复杂度要低得多。</p><p>这特别适用于应用程序级别的信息，比如哪个请求拥有最短响应时间，或者哪些 URL 遇到最多的错误，但它同样也适用于架构级别的监测，比如哪个服务的容器使用 CPU 资源超过了事先分配的资源数。</p><p>越来越多的软件部署需要一个<ruby>编排系统<rt> orchestration system</rt></ruby>，将应用程序的逻辑规划转化到物理的容器中。常见的编排系统包括 Kubernetes、Mesosphere DC/OS 和 Docker Swarm。团队可以用一个编排系统来（1）定义微服务（2）理解部署的每个服务的当前状态。你可以认为编排系统甚至比容器还重要。容器是短暂的，只有满足你的服务需求才会存在。</p><p>DevOps 团队应该将告警重点放到运行特征上，以尽可能贴近监控服务的体验。如果应用受到了影响，这些告警是评估事态的第一道防线。但是获得这些告警并不容易，除非你的监控系统是基于原生于容器的。</p>',18)),e("p",null,[e("ruby",null,[n(r,{href:"https://techcrunch.com/2016/04/27/lets-define-container-native/"},{default:l(()=>[...t[0]||(t[0]=[i("原生容器",-1)])]),_:1}),t[1]||(t[1]=e("rt",null,"Container-native",-1))]),t[2]||(t[2]=i("解决方案利用",-1)),t[3]||(t[3]=e("ruby",null,[i("编排元数据"),e("rt",null,"orchestration metadata")],-1)),t[4]||(t[4]=i("来动态聚合容器和应用程序数据，并按每个服务计算监控度量。根据您的编排工具，您可能想在不同层次进行深入检测。比如，在 Kubernetes 里，你通常有 Namespace、ReplicaSet、Pod 和一些其他容器。聚合这些不同的层，对排除逻辑故障是很有必要的，与构成服务的容器的物理部署无关。",-1))]),t[25]||(t[25]=a('<p><img src="http://thenewstack.io/wp-content/uploads/2016/09/servicemonitoring.jpg" alt=""></p><h4 id="_3、-监控弹性elastic和多地部署multi-location的服务" tabindex="-1">3、 监控<ruby>弹性<rt>Elastic</rt></ruby>和<ruby>多地部署<rt>Multi-Location</rt></ruby>的服务 <a class="header-anchor" href="#_3、-监控弹性elastic和多地部署multi-location的服务" aria-label="Permalink to “3、 监控弹性Elastic和多地部署Multi-Location的服务”">​</a></h4><p>弹性服务不是一个新概念，但是它在原生容器环境中的变化速度比在虚拟环境中快的多。迅速的变化会严重影响检测系统的正常运行。</p><p>监测传统的系统经常需要根据软件部署，手动调整检查指标。这种调整可以是具体的，如定义要捕获的单个指标，或基于应用程序在一个特定的容器中的操作配置要收集的数据。在小规模上（比如几十个容器）我们可以接受，但是再大规模就难以承受了。微服务的集中监控必须能够自由的随弹性服务而增长和缩减，无需人工干预。</p><p>比如，如果 DevOps 团队必须手动定义容器包含哪个服务需要监控，他们毫无疑问会失手，因为 Kubernetes 或者 Mesos 每天都会定期创建新的容器。同样，如果代码发布并置于生产环境时要求运维团队安装一个<ruby>定制的状态端点<rt>custom stats endpoint</rt></ruby>，也给开发者从 Docker 仓库获取基础镜像带来更多的挑战。</p><p>在生产环境中，建立面向跨越多个数据中心或多个云的复杂部署的监控，比如，如果你的服务跨越私有数据中心和 AWS，那么亚马逊的 AWS CloudWatch 就很难做到这一点。这就要求我们建立一个跨不同地域的监控系统，并可在动态的原生容器环境下运行。</p><h4 id="_4、-监控-api" tabindex="-1">4、 监控 API <a class="header-anchor" href="#_4、-监控-api" aria-label="Permalink to “4、 监控 API”">​</a></h4><p>在微服务环境中，API 接口是通用的。本质上，它们是将服务暴露给其它团队的唯一组件。事实上，API 的响应和一致性可以看作是“内部 SLA”，即使还没有定义一个正式的 SLA（服务等级协议）。</p><p>因此，API 接口的监控也是必要的。API 监控可以有不同的形式，但是很显然它绝对不是简单的二进制上下检查。例如，了解像时间函数这样的最常使用的<ruby>端点<rt>endpoint</rt></ruby>是有价值的。这使得团队可以看到服务使用的变化，无论是由于设计变更或用户的改变。</p><p>你也可以记录服务最缓慢的端点，这些可能揭示出重大的问题，或者至少指向需要在系统中做优化的区域。</p><p>最后，跟踪系统服务响应的能力是另一个很重要的能力，它主要是开发者使用，也能帮助你了解整体用户体验，同时将信息基于底层和应用程序视角分成两大部分。</p><h4 id="_5、-将您的监控映射到您的组织结构" tabindex="-1">5、 将您的监控映射到您的组织结构 <a class="header-anchor" href="#_5、-将您的监控映射到您的组织结构" aria-label="Permalink to “5、 将您的监控映射到您的组织结构”">​</a></h4><p>这篇文章着重在微服务和监控上，像其他科技文章一样，这是因为很多人都关注此层面。</p>',13)),e("p",null,[t[7]||(t[7]=i("对于那些熟悉",-1)),e("ruby",null,[n(r,{href:"https://en.wikipedia.org/wiki/Conway%27s_law"},{default:l(()=>[...t[5]||(t[5]=[i("康威定律",-1)])]),_:1}),t[6]||(t[6]=e("rt",null," Conway’s law",-1))]),t[8]||(t[8]=i("的人来说，系统的设计是基于开发团队的组织结构。创造更快，更敏捷的软件的压力推动了团队去思考重新调整他们的开发组织和管理它的规则。",-1))]),t[26]||(t[26]=e("p",null,[e("img",{src:"http://thenewstack.io/wp-content/uploads/2016/09/mapmonitoring.jpg",alt:""})],-1)),t[27]||(t[27]=e("p",null,"所以，如果他们想从这个新的软件架构（微服务）上获益，他们的团队必须将微服务映射到团队自身中。也就是说，他们需要更小的更松散耦合的团队，可以选择自己的方向只要能够满足整个需求即可。在每一个团队中，对于开发语言的使用，bug 的提交甚至工作职责都会有更大的控制能力。",-1)),t[28]||(t[28]=e("p",null,"DevOps 团队对此可以启用一个监控平台：让每一个微服务团队可以有自己的警报，度量指标，和控制面板，同时也要给出整体系统的视图。",-1)),t[29]||(t[29]=e("h3",{id:"总结",tabindex:"-1"},[i("总结 "),e("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),t[30]||(t[30]=e("p",null,"让微服务流行起来的是快捷。开发组织要想更快的为客户提供更多的功能，然后微服务技术就来了，架构转向微服务并且容器的流行让快捷开发成为可能，所有相关的进程理所当然的搭上了这辆火车。",-1)),t[31]||(t[31]=e("p",null,"最后，基本的监控原则需要适应伴随微服务而来的技术和结构。越早认识到这种转变的开发团队，能更早更容易的适应微服务这一新的架构。",-1)),t[32]||(t[32]=e("hr",null,null,-1)),e("p",null,[t[10]||(t[10]=i("via: ",-1)),n(r,{href:"http://thenewstack.io/five-principles-monitoring-microservices/"},{default:l(()=>[...t[9]||(t[9]=[i("http://thenewstack.io/five-principles-monitoring-microservices/",-1)])]),_:1})]),e("p",null,[t[15]||(t[15]=i("作者：",-1)),n(r,{href:"http://thenewstack.io/author/apurvadave/"},{default:l(()=>[...t[11]||(t[11]=[i("Apurva Dave",-1)])]),_:1}),t[16]||(t[16]=i(" ，",-1)),n(r,{href:"http://thenewstack.io/author/lorisdegioanni/"},{default:l(()=>[...t[12]||(t[12]=[i("Loris Degioanni",-1)])]),_:1}),t[17]||(t[17]=i(" 译者：",-1)),n(r,{href:"https://github.com/jiajia9linuxer"},{default:l(()=>[...t[13]||(t[13]=[i("jiajia9linuxer",-1)])]),_:1}),t[18]||(t[18]=i(" 校对：",-1)),n(r,{href:"https://github.com/jasminepeng"},{default:l(()=>[...t[14]||(t[14]=[i("jasminepeng",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=i("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原创编译，",-1)),n(r,{href:"https://linux.cn/"},{default:l(()=>[...t[20]||(t[20]=[i("Linux中国",-1)])]),_:1}),t[23]||(t[23]=i(" 荣誉推出",-1))])])}const C=o(d,[["render",m]]);export{k as __pageData,C as default};
